/** Frozen for legacy clients: same methods, same checked exceptions, same faults. */
@Deprecated(forRemoval = true)
interface LegacyPricing {
    double priceOf(String sku) throws LegacyFault;        // old, throws-based contract
}
final class LegacyPricingWindow implements LegacyPricing { // window over the new core
    private final PricingService core;                     // canonical model, no legacy types
    LegacyPricingWindow(PricingService core) { this.core = core; }
    @Override public double priceOf(String sku) throws LegacyFault {
        return LegacyMapping.toLegacyMinorUnits(core.quote(sku));   // explicit mapping
    }
}

